```typescript
import React, { useEffect, useState } from 'react';
import ConvertKitForm from './ConvertKitForm';
import { canCloseEmbed, getSubscriberEmail } from './emailGate';
import { CK_STORAGE_KEY } from './constants';

const HomePage = () => {
    const [showEmbed, setShowEmbed] = useState<boolean>(true);
    const [canCloseEmbed, setCanCloseEmbed] = useState<boolean>(true); // Added

    useEffect(() => {
      // Initialize showEmbed from localStorage
      const dismissalTime = localStorage.getItem(CK_STORAGE_KEY);
      if (dismissalTime) {
          const parsedTime = parseInt(dismissalTime, 10);
          if (!isNaN(parsedTime) && parsedTime > Date.now()) {
              setShowEmbed(false);
          }
      }
    }, []);

    // Timer for auto-close
    useEffect(() => {
        if (!showEmbed && !canCloseEmbed) { // Added showEmbed check to avoid running if hidden
            const timer = setTimeout(() => {
                setCanCloseEmbed(true);
            }, 10000);
            return () => clearTimeout(timer);
        }
    }, [canCloseEmbed, showEmbed]);

    // Listener for ConvertKit submission
    useEffect(() => {
        const handleCKSubmit = () => {
            setShowEmbed(false);
            const ninetyDaysInMs = 90 * 24 * 60 * 60 * 1000;
            localStorage.setItem(CK_STORAGE_KEY, (Date.now() + ninetyDaysInMs).toString());
        };

        // ConvertKit dispatches this event on document
        document.addEventListener('ck:form:submitted', handleCKSubmit);

        return () => {
            document.removeEventListener('ck:form:submitted', handleCKSubmit);
        };
    }, []);

    const handleClose = () => {
        setShowEmbed(false);
        localStorage.setItem(CK_STORAGE_KEY, (Date.now() + 1000 * 60 * 60 * 24).toString()); // 1 day
    };

    return (
        <div>
            {showEmbed && (
                <div style={{ position: 'relative' }}>
                    <button style={{ position: 'absolute', top: '10px', right: '10px' }} onClick={handleClose}>
                        X
                    </button>
                    <ConvertKitForm />
                </div>
            )}
            {!showEmbed && <p>Thank you for subscribing!</p>}
        </div>
    );
};

export default HomePage;
```

